import numpy as np, math, mujoco
import driver
r=driver.build()
if hasattr(r,"_resolve"): r._resolve()
def pos(): p,_=r.get_base_pose(); return np.asarray(p[:2],float)
def yaw(): _,rot=r.get_base_pose(); return math.atan2(float(rot[1,0]),float(rot[0,0]))
def rp():
    _,rot=r.get_base_pose(); rr=np.asarray(rot)
    pi=math.asin(max(-1,min(1,-float(rr[2,0])))); ro=math.atan2(float(rr[2,1]),float(rr[2,2]))
    return ro,pi
for _ in range(40): r.command_planar_velocity(0,0,0,0.02)
m,d=r.model,r.data
d.qpos[2]+=0.06; d.qvel[0]=0.5; d.qvel[1]=0.3; d.qvel[3]=0.7; d.qvel[4]=0.5
mujoco.mj_forward(m,d)
p0=pos(); t0=r.data.time
for i in range(90):
    e=p0-pos(); y=yaw(); c,s=math.cos(y),math.sin(y)
    bx=c*e[0]+s*e[1]; by=-s*e[0]+c*e[1]
    vx=float(np.clip(4.0*bx,-0.4,0.4)); vy=float(np.clip(4.0*by,-0.4,0.4))
    r.command_planar_velocity(vx,vy,0.0,0.02)
    ro,pi=rp(); t=r.data.time-t0
    if t<=0.55 and round(t*100)%5==0:
        print(f"t={t:.2f} rp=({abs(ro):.4f},{abs(pi):.4f})")
